  'chat_error.action_budget':
    "OpenHuman'ın saatlik eylem bütçesine ulaştınız. Bu, yapay zekâ sağlayıcınızın değil, yerel bir güvenlik sınırıdır. Süre penceresi kademeli olarak yenilenir; bu sohbet dizisinde sohbete devam edebilirsiniz ve araç yoğun adımlar bütçe doldukça yeniden başlar.",
  'chat_error.max_iterations':
    'Ajan, tek bir turda izin verilen en fazla araç adımını tamamlamadan çalıştırdı. Bu genellikle bir aracın sürekli başarısız olduğu anlamına gelir (çoğunlukla bir web isteğindeki hız sınırı). Alttaki sınır kalktığında aynı soruyu bu sohbet dizisinde yeniden deneyebilirsiniz.',
  'chat_error.turn_timeout':
    'Bu tur, tamamlanmadan süre bütçesini aştı ve takılı kalmaması için durduruldu. Bu genellikle bir araç çağrısının veya görev devredilen bir alt ajanın takıldığı anlamına gelir. Sorunuzu bu sohbet dizisinde yeniden deneyebilirsiniz.',
  'chat_error.empty_response':
    'Model boş bir yanıt döndürdü. Lütfen yeniden deneyin. Sorun devam ederse farklı bir model deneyin veya Bağlantılar → API anahtarları → LLM bölümünden kurulumunu kontrol edin.',
  'chat_error.chat_template_rejected':
    'Bu modelin sohbet şablonu isteği reddetti. Sorun model, sıcaklık veya API anahtarınız değil. Yerel araç çağırma desteği olmayan yerel modeller kendi sohbet şablonları üzerinden yönetilir ve bazı şablonlar bir araç adımının mesaj yapısını kabul etmez. Geçmişi sıfırlamak için yeni bir sohbet başlatın veya Bağlantılar → API anahtarları → LLM bölümünden yerel araç desteği olan bir model seçin.',
  'chat_error.rate_limited':
    'Yapay zekâ sağlayıcınız istekleri hız sınırına takıyor. Bu, sohbet dizisi düzeyinde bir engel değil, geçici bir sağlayıcı sınırıdır. Bu sohbet dizisinde yeniden deneyebilirsiniz.',
  'chat_error.rate_limited_billing':
    "Yapay zekâ sağlayıcınız istekleri faturalandırma veya plan nedenleriyle reddediyor (kredi tükendi, plan sınırı doldu veya model kullanılamıyor). Yeniden denemek işe yaramaz. Kredi yüklemek, planınızı yükseltmek veya farklı bir model seçmek için Ayarlar'ı açın.",
  'chat_error.managed_rate_limited':
    'Yapay zekâ sağlayıcınız istekleri hız sınırına takıyor. Bu sohbet dizisinde yeniden deneyebilirsiniz.',
  'chat_error.timeout':
    'İstek zaman aşımına uğradı. Lütfen bağlantınızı kontrol edip yeniden deneyin.',
  'chat_error.auth_error':
    'Yapay zekâ sağlayıcısıyla ilgili bir kimlik doğrulama sorunu var. Lütfen ayarlardan API anahtarınızı kontrol edin.',
  'chat_error.budget_exhausted':
    'Krediniz tükendiği için yönetilen (bulut) modeli şu anda çalıştıramıyorum. Devam etmek için kredi yükleyebilir veya bir plan seçebilirsiniz. Ollama gibi bir yerel modeli etkinleştirdiyseniz, Bağlantılar → API anahtarları → LLM bölümünden yönlendirmeyi "Kendi modellerinizi kullanın" olarak değiştirebilirsiniz.',
