    'Yapay zekâ hizmeti geçici olarak kullanılamıyor. Ekibimiz bilgilendirildi. Lütfen birazdan yeniden deneyin.',
  'chat_error.payload_too_large':
    'Mesajınız veya ekiniz bu model için çok büyük. Mesajı kısaltın, eki kaldırın veya yeni bir sohbet dizisi başlatın.',
